$ErrorActionPreference = "Stop"
function Normalize-LF([string]$text) { return $text.Replace("`r`n","`n").Replace("`r","`n") }
function Decode-B64([string]$b64) { return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64)) }
function Replace-Once([string]$text,[string]$old64,[string]$new64,[string]$label) {
  $text = Normalize-LF $text
  $old = Normalize-LF (Decode-B64 $old64)
  $new = Normalize-LF (Decode-B64 $new64)
  $idx = $text.IndexOf($old)
  if ($idx -lt 0) {
    if ($new.Length -gt 0 -and $text.Contains($new)) { return $text }
    throw "Expected block not found: $label. Pull latest main and do not commit partial changes."
  }
  return $text.Substring(0,$idx) + $new + $text.Substring($idx + $old.Length)
}
function Write-Utf8NoBom([string]$path,[string]$text) {
  $enc = New-Object Text.UTF8Encoding($false)
  [IO.File]::WriteAllText($path,(Normalize-LF $text),$enc)
}
